import { ResourceAllocationData } from '../types';
import { filterKpiContentByLabels } from './filterKpiContentByLabels';
import { normalizeKpiContent } from './normalizeKpiContent';

const hasRenderableChartAtIndex = (
  media: ReturnType<typeof filterKpiContentByLabels>,
  nwm: ReturnType<typeof filterKpiContentByLabels>,
  sponsorship: ReturnType<typeof filterKpiContentByLabels>,
  index: number,
): boolean =>
  Boolean(
    media.datasets[index] || sponsorship.datasets[index] || nwm.datasets[index],
  );

export const hasResourceAllocationChartData = (
  content?: ResourceAllocationData | null,
  selectedComparisons: string[] | null = null,
): boolean => {
  if (!content || content.empty) {
    return false;
  }

  const media = filterKpiContentByLabels(
    normalizeKpiContent(content.media?.media),
    selectedComparisons,
  );
  const nwm = filterKpiContentByLabels(
    normalizeKpiContent(content.non_working_money?.non_working_money),
    selectedComparisons,
  );
  const sponsorship = filterKpiContentByLabels(
    normalizeKpiContent(content.sponsorship_activation?.sponsorship_activation),
    selectedComparisons,
  );

  return media.labels.some((_, index) =>
    hasRenderableChartAtIndex(media, nwm, sponsorship, index),
  );
};
